/**
 * 标准组件类型
 * @description 标准化组件的基础类型定义，包含组件的所有核心属性
 * @template ComponentProp - 组件属性类型，默认为 AllComponentType
 * @template Option - 组件选项类型，默认为 any
 * @template Data - 组件数据类型，默认为 any
 */
interface StandardComponentType<ComponentProp extends AllComponentType = AllComponentType, Option = any, Data = any> {
    /** 组件ID */
    id: number;
    /** 组件基础配置 */
    component: {
        /** 组件属性 */
        prop: ComponentProp;
        /** 宽度 */
        width: number;
        /** 高度 */
        height: number;
        /** 组件名称 */
        name: string;
    };
    /** 是否为分组（可选） */
    group?: boolean;
    /** 是否被选中（可选） */
    selected?: boolean;
    /** 子组件列表（可选） */
    children?: ComponentType[];
    /** 组件名称 */
    name: string;
    /** 左边距 */
    left: number;
    /** 顶边距 */
    top: number;
    /** 是否锁定 */
    isLock?: boolean;
    /** Z轴层级 */
    zIndex: number;
    /** 是否显示 */
    display: boolean;
    /** 组件选项配置 */
    option: Option;
    /** 组件数据 */
    data: Data;
    /** 组件图片 */
    img: string;
    /** 组件标题 */
    title: string;
    /** 监听参数列表 */
    listenArgs: ListenArg[];
    /** 回调参数列表 */
    cbArgs: Callback[];
    /** 是否开启过滤器 */
    openFilter?: boolean;
    /** 数据源 */
    dataSource: DataSourceType;
    /** 数据类型 */
    dataType: DataType;
    /** 数据映射配置列表 */
    dataRemark?: DataRemark[];
    /** 事件列表 */
    events: Event[];
    /** 加密事件列表（可选） */
    encodes?: EncodeEvent[];
    /** URL（可选） */
    url?: string;
    /** 路径（可选） */
    path?: string;
    /** 数据查询（可选） */
    dataQuery?: string;
    /** 加载动画配置 */
    loadAnimation: Animation;
    /** 预设子组件列表（可选） */
    presetChild?: ChildComponent[];
    /** 素材库条目列表（可选）。注意不是 MinioResource，见 ComponentMinioAsset 的说明 */
    minioArr?: ComponentMinioAsset[];
    /** 父组件ID（可选） */
    parent?: number;
    /** 单位铺满类型（可选） */
    unitPavenType?: "percent";
}
/**
 * 组件类型（允许任意扩展字段）
 * @description 标准组件类型的扩展版本，允许添加任意字段，但限制某些冲突字段
 * @template ComponentProp - 组件属性类型，默认为 AllComponentType
 * @template Option - 组件选项类型，默认为 any
 * @template Data - 组件数据类型，默认为 any
 */
type ComponentType<ComponentProp extends AllComponentType = AllComponentType, Option = any, Data = any> = StandardComponentType<ComponentProp, Option, Data> & {
    /** 其他任意属性 */
    [key: string]: any;
} & {
    /** 宽度字段被限制（可选） */
    width?: never;
    /** 高度字段被限制（可选） */
    height?: never;
    /** 父级动态面板ID列表（可选） */
    parentDynamicPanelId?: number[];
    /** 父级编码ID（可选） */
    parentEncodeId?: string;
};

