    gaussianBlur: number;
    /** 亮度：屏幕亮度调节，1为正常，小于1变暗，大于1变亮 */
    brightness: number;
    /** 对比度：对比度调节，1为正常，小于1降低对比度，大于1增加对比度 */
    contrast: number;
    /** 灰度：灰度效果，0为彩色，1为完全灰度 */
    grayscale: number;
    /** 色调：色相旋转角度，0-360度 */
    hue: number;
    /** 饱和度：饱和度调节，0为完全去色，1为正常 */
    saturate: number;
    /** 反转：颜色反转，0为正常，1为完全反转 */
    invert: number;
    /** 棕褐色：棕褐色滤镜效果，0为正常，1为最大效果 */
    sepia: number;
    /** 色相旋转：色相旋转角度，单位为度 */
